import { useState } from "react";
import "./App.css";

function App() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [remember, setRemember] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!email.trim() || !password) {
      setError("Please enter your email and password.");
      return;
    }
    if (password.length < 6) {
      setError("Password must be at least 6 characters.");
      return;
    }

    setError("");
    setLoading(true);

    try {
      // TODO: replace with your real backend call, e.g.
      // const res = await fetch("http://localhost:5000/api/auth/login", {
      //   method: "POST",
      //   headers: { "Content-Type": "application/json" },
      //   body: JSON.stringify({ email, password }),
      // });
      await new Promise((resolve) => setTimeout(resolve, 800));
      console.log("Login:", { email, remember });
    } catch (err) {
      setError("Something went wrong. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="page">
      <div className="background-overlay"></div>

      <div className="auth-container">
        {/* LEFT SECTION */}
        <section className="left-section">
          <div className="brand">
            <div className="brand-mark">C</div>
            <span className="brand-name">CampusVerse</span>
          </div>

          <div className="quote">
            <h2>"Learn. Share. Grow together."</h2>
            <p>
              A place where students discover, share and access knowledge
              together.
            </p>
          </div>
        </section>

        {/* RIGHT SECTION */}
        <section className="right-section">
          <div className="login-box">
            <a href="/" className="back-link">
              ← Back to CampusVerse
            </a>

            <div className="login-heading">
              <h1>Welcome back</h1>
              <p>Login to access your study materials.</p>
            </div>

            <form onSubmit={handleSubmit} noValidate>
              <div className="field">
                <label htmlFor="email">Email Address</label>
                <input
                  type="email"
                  id="email"
                  placeholder="Enter your email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                />
              </div>

              <div className="field">
                <label htmlFor="password">Password</label>
                <div className="password-wrap">
                  <input
                    type={showPassword ? "text" : "password"}
                    id="password"
                    placeholder="Enter your password"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                  />
                  <button
                    type="button"
                    className="toggle-password"
                    onClick={() => setShowPassword((s) => !s)}
                  >
                    {showPassword ? "Hide" : "Show"}
                  </button>
                </div>
              </div>

              {error && <p className="error-message">{error}</p>}

              <div className="form-options">
                <label className="remember">
                  <input
                    type="checkbox"
                    checked={remember}
                    onChange={(e) => setRemember(e.target.checked)}
                  />
                  <span>Remember me</span>
                </label>

                <a href="/forgot-password" className="forgot">
                  Forgot password?
                </a>
              </div>

              <button
                type="submit"
                className="login-button"
                disabled={loading}
              >
                {loading ? "Logging in..." : "Login"}
              </button>
            </form>

            <div className="signup">
              Don't have an account? <a href="/signup">Create an account</a>
            </div>
          </div>
        </section>
      </div>
    </div>
  );
}

export default App;
